// Width of a run of digits (other characters are skipped).
inline int width(const char* s) {
  int w = 0;
  for (; *s; ++s) if (*s >= '0' && *s <= '9') w += W[*s - '0'];
  return w;
}
// Draws digits with their top at y, centred on cx, as row runs.
template <class Canvas>
inline void drawCentered(Canvas& c, int cx, int y, const char* s, bool black = true) {
  int x = cx - width(s) / 2;
  for (; *s; ++s) {
    if (*s < '0' || *s > '9') continue;
    const int d = *s - '0', dw = W[d], stride = (dw + 7) / 8;
    const uint8_t* bits = BITS + OFF[d];
    for (int row = 0; row < H; row++) {
      int run = -1;
      for (int col = 0; col <= dw; col++) {
        const bool ink = col < dw && (pgm_read_byte(bits + row * stride + col / 8) & (0x80 >> (col & 7)));
        if (ink && run < 0) run = col;
        if (!ink && run >= 0) {
          c.fillRect(x + run, y + row, col - run, 1, black);
          run = -1;
        }
      }
    }
    x += dw;
  }
}
